/// Raw PNG bytes of the app logo.
final Uint8List kAppLogoBytes = base64Decode(_logoBase64);

/// The ArxivLibrary logo: the gold-book mark in a rounded tile.
class AppLogoImage extends StatelessWidget {
  const AppLogoImage({super.key, this.size = 28});

  final double size;

  @override
  Widget build(BuildContext context) {
    return ClipRRect(
      borderRadius: BorderRadius.circular(size * 0.22),
      child: Image.memory(
        kAppLogoBytes,
        width: size,
        height: size,
        fit: BoxFit.cover,
        gaplessPlayback: true,
      ),
    );
  }
}
